from pathlib import Path
p=Path('src/components/personal-account.tsx');s=p.read_text(encoding='utf-8')
s=s.replace("[staffFullName,setStaffFullName]=useState('')","[staffFullName,setStaffFullName]=useState(''),[staffEditField,setStaffEditField]=useState(''),[originalStaffEmail,setOriginalStaffEmail]=useState('')")
s=s.replace("setEditingStaff(false)","setEditingStaff(false);setStaffEditField('');setOriginalStaffEmail('')")
s=s.replace("setEditingStaff(true)","setEditingStaff(true);setStaffEditField('');setOriginalStaffEmail(name)")
s=s.replace("if(!editingStaff&&target.staff.some(value=>value.toLowerCase()===email))", "if(target.staff.some(value=>value.toLowerCase()===email&&(!editingStaff||value!==originalStaffEmail)))")
s=s.replace("staff:[...new Set([...s.staff,email])],staffRights:{...s.staffRights,[email]:staffPermissions},staffNames:{...s.staffNames,[email]:staffFullName.trim()}","staff:[...new Set([...s.staff.filter(value=>!editingStaff||value!==originalStaffEmail),email])],staffRights:{...Object.fromEntries(Object.entries(s.staffRights||{}).filter(([key])=>!editingStaff||key!==originalStaffEmail)),[email]:staffPermissions},staffNames:{...Object.fromEntries(Object.entries(s.staffNames||{}).filter(([key])=>!editingStaff||key!==originalStaffEmail)),[email]:staffFullName.trim()}")
a='<Input id="staff-full-name" autoFocus required autoComplete="name" placeholder="Фамилия Имя Отчество" value={staffFullName} onChange={e=>setStaffFullName(e.target.value)}/>'
b='''<div className="staff-identity-field"><Input id="staff-full-name" autoFocus={!editingStaff} readOnly={editingStaff&&staffEditField!=='name'} required autoComplete="name" placeholder="Фамилия Имя Отчество" value={staffFullName} onChange={e=>setStaffFullName(e.target.value)}/>{editingStaff&&<Button type="button" variant="ghost" size="icon" aria-label="Редактировать ФИО сотрудника" onClick={()=>{setStaffEditField('name');requestAnimationFrame(()=>document.getElementById('staff-full-name')?.focus())}}><Pencil size={15}/></Button>}</div>'''
assert a in s;s=s.replace(a,b)
a='<Input id="new-staff-email" type="email" required readOnly={editingStaff} placeholder="name@example.com" value={newStaffEmail} onChange={e=>setNewStaffEmail(e.target.value)}/>'
b='''<div className="staff-identity-field"><Input id="new-staff-email" type="email" required readOnly={editingStaff&&staffEditField!=='email'} placeholder="name@example.com" value={newStaffEmail} onChange={e=>setNewStaffEmail(e.target.value)}/>{editingStaff&&<Button type="button" variant="ghost" size="icon" aria-label="Редактировать email сотрудника" onClick={()=>{setStaffEditField('email');requestAnimationFrame(()=>document.getElementById('new-staff-email')?.focus())}}><Pencil size={15}/></Button>}</div>'''
assert a in s;s=s.replace(a,b);p.write_text(s,encoding='utf-8')
